  "OtherConvertEasyChatWordsToString": {
    returnType: "u8 *",
    params: "u8 *dest, const u16 *src, u16 columns, u16 rows",
    callsTo: ["CopyEasyChatWord"],
    lineCount: 41,
    bodyC: "u16 i, j, k;\n    u16 numColumns;\n    int notEmpty, lineNumber;\n\n    numColumns = columns;\n    lineNumber = 0;\n    columns--;\n    for (i = 0; i < rows; i++)\n    {\n        const u16 *str = src;\n        notEmpty = FALSE;\n        for (j = 0; j < numColumns; j++)\n        {\n            if (str[j] != EC_EMPTY_WORD)\n                notEmpty = TRUE;\n        }\n\n        if (!notEmpty)\n        {\n            src += numColumns;\n            continue;\n        }\n\n        for (k = 0; k < columns; k++)\n        {\n            dest = CopyEasyChatWord(dest, *src);\n            if (*src != EC_EMPTY_WORD)\n            {\n                *dest = CHAR_SPACE;\n                dest++;\n            }\n\n            src++;\n        }\n\n        dest = CopyEasyChatWord(dest, *(src++));\n        if (lineNumber == 0)\n            *dest = CHAR_NEWLINE;\n        else\n            *dest = CHAR_PROMPT_SCROLL;\n\n        dest++;\n        lineNumber++;\n    }\n\n    dest--;\n    *dest = EOS;\n    return dest;",
  },
