  "WordSelectPageScrollDown": {
    returnType: "static bool8",
    params: "void",
    callsTo: ["GetLowerWindowScrollOffset","GetWordSelectScrollOffset","InitLowerWindowScroll","IsDma3ManagerBusyWithBgCopy","PrintWordSelectRowsPageDown","UpdateLowerWindowScroll","UpdateScrollIndicatorsVisibility","UpdateStartSelectButtonsVisibility","UpdateWordSelectCursorPos"],
    lineCount: 28,
    bodyC: "switch (sScreenControl->funcState)\n    {\n    case 0:\n        PrintWordSelectRowsPageDown();\n        sScreenControl->funcState++;\n        break;\n    case 1:\n        if (!IsDma3ManagerBusyWithBgCopy())\n        {\n            s16 scrollChange = GetWordSelectScrollOffset() - GetLowerWindowScrollOffset();\n            InitLowerWindowScroll(scrollChange, 8);\n            sScreenControl->funcState++;\n        }\n        break;\n    case 2:\n        if (!UpdateLowerWindowScroll())\n        {\n            UpdateWordSelectCursorPos();\n            UpdateScrollIndicatorsVisibility();\n            UpdateStartSelectButtonsVisibility();\n            sScreenControl->funcState++;\n            return FALSE;\n        }\n        break;\n    case 3:\n        return FALSE;\n    }\n\n    return TRUE;",
  },
